        V("akala-m21", "akalà", "assumption; to think", say="a-KA-laQ", pos="noun", group="more", note="The opening paragraph prints akalá (to think). From: Ang akalà ko Amerikáno siyá = My assumption is that he is an American."),
        V("isip-m21", "isip", "to think", pos="noun", group="more", note="Lesson 14 prints ísip."),
        V("pumunta-m21", "pumuntá", "to go; can also mean to come", say="pu-mun-TA", pos="verb", group="more", note="From: Pumuntá ka díto = Come here."),
