        V("sagot-m21", "sagot", "answer", pos="noun", group="more", note="From: Ang sagot niyá ay tila mali = His/her answer seems wrong."),
        V("mali-m21", "mali", "wrong", pos="adj", group="more", note="From: Ang sagot niyá ay tila mali = His/her answer seems wrong. The exercises print malí."),
        V("matalino-m21", "matalíno", "intelligent", say="ma-ta-LI-no", pos="adj", group="more", note="Lesson 8 prints matalino. From: Sa akalà ko ikaw ay matalíno = I think you are an intelligent man."),
        V("may-sakit-m21", "may sakít", "sick", say="may sa-KIT", pos="phrase", group="more", note="The vocabulary list prints maysakít. From: Sa akalà nila, siyá'y may sakít = They think he is sick."),
        V("ng-lahat-m21", "ng lahat", "of everybody", pos="phrase", group="more"),
