        V("iniisip-m21", "iniísip", "thinks about", say="i-ni-I-sip", pos="verb", group="more", note="From: Iniísip niyá ang kanyáng mga sinásabi = She thinks about what she says."),
        V("sinasabi-m21", "sinásabi", "what (she) says", say="si-NA-sa-bi", pos="verb", group="more", note="From: Iniísip niyá ang kanyáng mga sinásabi = She thinks about what she says."),
        V("magagawa-m21", "magagawâ", "what can be done", say="ma-ga-ga-waQ", pos="verb", group="more", note="From: Mag-isíp ka ng magagawâ = (You) Think of what can be done."),
        V("dito-m21", "díto", "here", say="DI-to", pos="adv", group="more", note="Lesson 13 prints dito. From: Pumuntá ka díto = Come here."),
        V("doon-m21", "doón", "there", say="do-ON", pos="adv", group="more", note="From: Pumuntá ka doón = Go there."),
