        V("maglakad-m21", "maglákad", "walk (you go to walk)", say="mag-LA-kad", pos="verb", group="more", note="Lesson 14 prints maglakád. From: Maglákad ka = You go to walk (or You walk)."),
        V("natutulog-m21", "natútúlog", "are sleeping", say="na-TU-TU-log", pos="verb", group="more", note="Lesson 12 prints natutúlog. From: Natútúlog sila sa kabilâng kuwarto = They are sleeping in the next room."),
        V("kabilang-m21", "kabilâng", "next (the next room)", say="ka-bi-lang", pos="adj", group="more", note="From: Natútúlog sila sa kabilâng kuwarto = They are sleeping in the next room."),
        V("kuwarto-m21", "kuwarto", "room", pos="noun", group="more", note="From: Natútúlog sila sa kabilâng kuwarto = They are sleeping in the next room."),
